//! The percentage widths of a child of a vertical root refer to the root's
//! width, which is its block size, only when the content of the root does not
//! decide that width. A float, an inline-block or an absolutely positioned box
//! that shrinks to fit has the width of its content, so an inline-block that
//! states `width: 50%` inside it reads `auto`, whatever the depth, and so do its
//! `min-width` and `max-width`. A horizontal child of such a root, an
//! orthogonal flow, refers to the page area instead, as the initial containing
//! block stands in for the width the content has not decided yet (CSS Writing
//! Modes 4 §7.3.1). A width the root states, or an absolutely positioned box
//! takes from both of its insets, is a basis.
//!
//! The expected border boxes were recorded from Chromium for the same markup in
//! an 800px by 600px viewport with no body margin.

use raikiri_html::{
    FontCollectionBuilder, LayoutOptions, LayoutStatus, RenderResources, layout,
    parse_html_with_resources,
};
use raikiri_traits::{LayoutConfig, PageDefaults};

const AHEM: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/data/text-autospace/Ahem.ttf"
));

/// A border box `(x, y, width, height)`.
type Rect = (f32, f32, f32, f32);

/// A case: its name, its markup, and the border boxes by id.
type Case = (&'static str, &'static str, &'static [(&'static str, Rect)]);

/// The border boxes of the elements of `body` with an `id` on the first page.
fn border_boxes(body: &str) -> Vec<(String, Rect)> {
    let html = format!(
        "<!DOCTYPE html><style>@page {{ size: 800px 600px; margin: 0 }} \
         body {{ margin: 0; font: 10px/10px Ahem }} div {{ box-sizing: border-box }}</style>{body}"
    );
    let fonts = FontCollectionBuilder::new()
        .font_bytes("Ahem", AHEM.to_vec())
        .build()
        .expect("fonts");
    let resources = RenderResources::new().fonts(fonts);
    let doc = parse_html_with_resources(html.as_bytes(), &resources).expect("parse");
    let status = layout(
        &doc,
        PageDefaults::default(),
        LayoutConfig::default(),
        LayoutOptions::new().resources(&resources),
    )
    .expect("layout");
    let LayoutStatus::Completed(result) = status else {
        panic!("expected a complete layout");
    };
    let page = result.pages().next().expect("a page");
    let dom = page.dom();
    page.fragments()
        .filter_map(|fragment| {
            let id = dom.attr(fragment.node(), "id")?;
            let rect = fragment.rect();
            Some((id.to_owned(), (rect.x, rect.y, rect.width, rect.height)))
        })
        .collect()
}

/// Layout units are 1/64px; allow a little more for the 32-bit sums.
const TOLERANCE: f32 = 0.02;

fn check(name: &str, body: &str, expected: &[(&str, Rect)]) {
    let actual = border_boxes(body);
    for &(id, (x, y, width, height)) in expected {
        let found = actual
            .iter()
            .find(|(box_id, _)| box_id == id)
            .unwrap_or_else(|| panic!("{name}: no fragment for #{id} in {body}"))
            .1;
        let close = |a: f32, b: f32| (a - b).abs() <= TOLERANCE;
        assert!(
            close(found.0, x)
                && close(found.1, y)
                && close(found.2, width)
                && close(found.3, height),
            "{name}: {body}: #{id} is {found:?}, expected {:?}",
            (x, y, width, height)
        );
    }
}

fn check_case(&(name, body, expected): &Case) {
    check(name, body, expected);
}

#[test]
fn nested_percentage_widths_in_a_content_sized_vertical_root_read_as_auto() {
    // A float, an inline-block and an absolutely positioned root, nested up to
    // three levels deep, with `width`, `min-width` and `max-width`.
    NESTED_IN_CONTENT_SIZED_ROOT.iter().for_each(check_case);
}

#[test]
fn nested_percentage_widths_in_a_vertical_root_of_a_stated_width_refer_to_it() {
    NESTED_IN_ROOT_OF_STATED_WIDTH.iter().for_each(check_case);
}

#[test]
fn nested_percentage_widths_in_an_absolute_vertical_root_that_shrinks_to_fit_read_as_auto() {
    // Only one of `left` and `right`, or a keyword width, leaves the width to
    // the content.
    NESTED_IN_ABSOLUTE_ROOT_THAT_SHRINKS_TO_FIT
        .iter()
        .for_each(check_case);
}

#[test]
fn nested_percentage_widths_in_an_absolute_vertical_root_of_a_definite_width_refer_to_it() {
    // A stated width, both insets, or `stretch` fix the width.
    NESTED_IN_ABSOLUTE_ROOT_OF_DEFINITE_WIDTH
        .iter()
        .for_each(check_case);
}

#[test]
fn a_horizontal_inline_block_in_a_content_sized_vertical_root_refers_to_the_page_width() {
    HORIZONTAL_INLINE_BLOCK_IN_VERTICAL_ROOT
        .iter()
        .for_each(check_case);
}

#[test]
fn a_horizontal_inline_block_in_a_vertical_page_refers_to_the_page_width() {
    HORIZONTAL_INLINE_BLOCK_IN_VERTICAL_PAGE
        .iter()
        .for_each(check_case);
}

